from ._commissioning import Commissioning


class commissioning(object):
    """
    Library responsible for performing commissioning via OAM webUI using SCF file.
    The SCF file can be obtained from OAM VM.
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self._commissioning = Commissioning()

    def commission(self, oam_ip, scf_xml,
                   timeout_create_session=Commissioning.TIMEOUT_CREATE_SESSION,
                   timeout_vm_availability=Commissioning.TIMEOUT_VM_AVAILABILITY,
                   expected_phase=Commissioning.DEFAULT_EXPECTED_STARTUP_PHASE,
                   user=Commissioning.DEFAULT_OAM_CREDENTIALS.user,
                   password=Commissioning.DEFAULT_OAM_CREDENTIALS.password,
                   oam_reboot_time=Commissioning.DEFAULT_REBOOT_TIME):
        """
        Performs commissioning using SCF file on OAM.
        How it works:

        #. Try to connect to oam for `timeout_create_session` seconds.
        #. Uploads file to OAM via REST API.
        #. Wait for 1 minute until OAM VM shut downs.
        #. Try to connect to oam for `timeout_create_session` seconds.
        #. Wait until current startup phase equals expected startup phase.
           Timeout is defined by timeout_vm_availability.
        #. Resets taf.transport.ssh cache

        :param oam_ip: IP of OAM
        :param scf_xml: path to SCF file
        :param timeout_create_session: timeout for creating REST session with OAM
        :param timeout_vm_availability: timeout for virtual machine availability
        :param expected_phase: phase which should be reched before commissioning \
        returns control. Currently there are following phases:

            * 1 - Startup ongoing, enabling virtual machines...
            * 2 - Startup ongoing, enbaling RAP...
            * 3 - Startup ongoing, enbaling radio...
            * 4 - Name unknown due to lack of documentation regarding OAM REST API
            * 5 - Name unknown due to lack of documentation regarding OAM REST API
        :param user: change default user in OAM Credentials. If empty default value will be used.
        :param password: change default password in OAM Credentials. If empty default value will be used.
        :param oam_reboot_time: time required for oam to reboot before trying to check if oam is available (default:60).
        """
        self._commissioning.commission(oam_ip, scf_xml, timeout_create_session,
                                       float(timeout_vm_availability),
                                       expected_phase=int(expected_phase),
                                       oam_credentials=Commissioning.OAMCredentials(user, password),
                                       oam_reboot_time=float(oam_reboot_time))

    def get_scf_from_oam_vm(self, scf_remote_dir, scf_filename, log_path, oam_connection=Commissioning.OAM_CONNECTION):
        """
        Returns path of SCF file downloaded from remote directory.
        Connection to OAM VM must be created before starting this keyword.

        :param scf_remote_dir: remote directory where SCF file exists
        :param scf_filename: SCF filename
        :param log_path: local path where SCF file will be stored
        :param oam_connection: connection alias, defaults to "OAM"
        :return: path to local SCF file
        """
        return self._commissioning.get_scf_from_oam_vm(scf_remote_dir, scf_filename, log_path, oam_connection)

    def modify_scf(self, input_scf, output_scf, parameters_lists):
        """
        Modifies provided SCF file and saves it to provided path.

        :param input_scf: path to SCF file
        :param output_scf: path where modified SCF file will be stored
        :param parameters_lists: list of dictionaries with values to modify
        """
        self._commissioning.modify_scf(input_scf, output_scf, parameters_lists)

    def wait_for_oam_node_port(self, oam_node_ip,
                               timeout=Commissioning.TIMEOUT_OAM_NODE_PORT,
                               interval=5,
                               port=Commissioning.OAM_PORT):
        """
        Checks if port is open for provided IP address.

        :param oam_node_ip: IP address of OAM node
        :param timeout: timeout in seconds for checking if port is open, defaults to 420
        :param interval: number of seconds between checks, defaults to 5
        :param port: OAM node port, defaults to 443
        """
        timeout = int(timeout)
        interval = int(interval)
        port = int(port)
        self._commissioning.wait_for_oam_node_port(oam_node_ip, timeout, interval, port)

    def wait_for_siteOAM(self, alias, timeout=Commissioning.TIMEOUT_SITE_OAM, interval=2):
        """
        Checks correctness of log file.

        :param alias: connection alias
        :param timeout: timeout in seconds for checks, defaults to 400
        :param interval: number of seconds between checks, defaults to 2
        """
        self._commissioning.wait_for_siteOAM(alias, timeout, interval)
